// src/pages/ChatPage.jsx
import { useState, useRef, useEffect } from 'react';
import { useParams } from 'react-router-dom';
import APIService from '../services/api';
import ReactMarkdown from 'react-markdown';

export default function ChatPage() {
  const { id } = useParams();
  const [messages,    setMessages]    = useState([]);
  const [input,       setInput]       = useState('');
  const [vin,         setVin]         = useState('');
  const [loading,     setLoading]     = useState(false);
  const [streaming,   setStreaming]   = useState(false);
  const [convId,      setConvId]      = useState(id || null);
  const [streamText,  setStreamText]  = useState('');
  const bottomRef = useRef(null);

  useEffect(() => {
    if (id) loadConversation(id);
  }, [id]);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, streamText]);

  async function loadConversation(cid) {
    try {
      const conv = await APIService.getConversation(cid);
      setMessages(conv.messages.map(m => ({ role: m.role, content: m.content })));
    } catch {}
  }

  async function sendMessage(e) {
    e.preventDefault();
    if (!input.trim() || loading) return;

    const userMsg = input.trim();
    setInput('');
    setMessages(prev => [...prev, { role: 'user', content: userMsg }]);
    setStreaming(true);
    setStreamText('');

    try {
      let full = '';
      let newConvId = convId;

      for await (const chunk of APIService.streamMessage(userMsg, convId, vin || undefined)) {
        if (chunk.type === 'conversation_id') {
          newConvId = chunk.id;
          setConvId(chunk.id);
        }
        if (chunk.type === 'token') {
          full += chunk.text;
          setStreamText(full);
        }
        if (chunk.type === 'done') {
          setMessages(prev => [...prev, { role: 'assistant', content: full }]);
          setStreamText('');
        }
      }
    } catch (err) {
      setMessages(prev => [...prev, { role: 'assistant', content: 'Something went wrong. Please try again.' }]);
      setStreamText('');
    } finally {
      setStreaming(false);
    }
  }

  return (
    <div style={{ display:'flex', flexDirection:'column', height:'100%' }}>

      {/* Topbar */}
      <div style={{ height:46, padding:'0 18px', borderBottom:'0.5px solid #D0DCE8', display:'flex', alignItems:'center', justifyContent:'space-between', background:'#fff', flexShrink:0 }}>
        <div style={{ display:'flex', alignItems:'center', gap:8, fontSize:13, fontWeight:500, color:'#1C2B3A' }}>
          <i className="ti ti-message-2" style={{ fontSize:15, color:'#607D8B' }} aria-hidden="true" />
          {convId ? 'Conversation' : 'New conversation'}
        </div>
        <div style={{ display:'flex', gap:5 }}>
          <button style={{ width:28, height:28, padding:0, display:'flex', alignItems:'center', justifyContent:'center' }} aria-label="Export">
            <i className="ti ti-download" style={{ fontSize:14 }} aria-hidden="true" />
          </button>
        </div>
      </div>

      {/* Messages */}
      <div style={{ flex:1, padding:18, overflowY:'auto', display:'flex', flexDirection:'column', gap:14 }}>

        {messages.length === 0 && !streaming && (
          <div style={{ flex:1, display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', gap:12, color:'#90A4AE', textAlign:'center' }}>
            <div style={{ width:48, height:48, background:'#E1F5EE', borderRadius:12, display:'flex', alignItems:'center', justifyContent:'center', fontSize:22, fontWeight:500, color:'#0F6E56' }}>L</div>
            <div style={{ fontSize:15, fontWeight:500, color:'#607D8B' }}>Ask LUMI AI anything automotive</div>
            <div style={{ fontSize:12, color:'#90A4AE' }}>Enter a VIN above to ground responses in real vehicle data</div>
            <div style={{ display:'flex', gap:8, flexWrap:'wrap', justifyContent:'center', marginTop:4 }}>
              {['What is the TCO for a 2022 Toyota Camry over 5 years?', 'Compare Ford F-150 vs Chevy Silverado for fleet use', 'What maintenance is due at 90,000 miles on a Honda CR-V?'].map(q => (
                <button key={q} onClick={() => setInput(q)} style={{ padding:'6px 12px', fontSize:12, background:'#F5F8FC', border:'0.5px solid #D0DCE8', borderRadius:8, color:'#1C2B3A' }}>
                  {q}
                </button>
              ))}
            </div>
          </div>
        )}

        {messages.map((m, i) => (
          <div key={i} style={{ display:'flex', gap:9, alignItems:'flex-start', flexDirection: m.role === 'user' ? 'row-reverse' : 'row' }}>
            <div style={{ width:26, height:26, borderRadius:'50%', flexShrink:0, display:'flex', alignItems:'center', justifyContent:'center', fontSize:10, fontWeight:500, background: m.role === 'user' ? '#0D2FA3' : '#E1F5EE', color: m.role === 'user' ? '#fff' : '#0F6E56' }}>
              {m.role === 'user' ? 'U' : 'L'}
            </div>
            <div style={{ padding:'10px 13px', borderRadius: m.role === 'user' ? '12px 0 12px 12px' : '0 12px 12px 12px', background: m.role === 'user' ? '#0D2FA3' : '#F5F8FC', color: m.role === 'user' ? '#fff' : '#1C2B3A', maxWidth: m.role === 'user' ? 320 : 480, fontSize:12.5, lineHeight:1.6 }}>
              {m.role === 'assistant'
                ? <ReactMarkdown>{m.content}</ReactMarkdown>
                : m.content}
            </div>
          </div>
        ))}

        {streaming && streamText && (
          <div style={{ display:'flex', gap:9, alignItems:'flex-start' }}>
            <div style={{ width:26, height:26, borderRadius:'50%', flexShrink:0, display:'flex', alignItems:'center', justifyContent:'center', fontSize:10, fontWeight:500, background:'#E1F5EE', color:'#0F6E56' }}>L</div>
            <div style={{ padding:'10px 13px', borderRadius:'0 12px 12px 12px', background:'#F5F8FC', color:'#1C2B3A', maxWidth:480, fontSize:12.5, lineHeight:1.6 }}>
              <ReactMarkdown>{streamText}</ReactMarkdown>
            </div>
          </div>
        )}

        {streaming && !streamText && (
          <div style={{ display:'flex', gap:9, alignItems:'center' }}>
            <div style={{ width:26, height:26, borderRadius:'50%', flexShrink:0, display:'flex', alignItems:'center', justifyContent:'center', fontSize:10, fontWeight:500, background:'#E1F5EE', color:'#0F6E56' }}>L</div>
            <div style={{ display:'flex', alignItems:'center', gap:7, color:'#90A4AE', fontSize:12 }}>
              <span className="loading-dot" />
              Thinking…
            </div>
          </div>
        )}

        <div ref={bottomRef} />
      </div>

      {/* Input area */}
      <div style={{ padding:'12px 18px', borderTop:'0.5px solid #D0DCE8', background:'#fff', flexShrink:0 }}>
        <div style={{ display:'flex', gap:7, marginBottom:7 }}>
          <input value={vin} onChange={e => setVin(e.target.value)} placeholder="VIN (optional) — grounds LUMI AI in real vehicle data" style={{ flex:1, height:31, fontSize:12, background:'#F5F8FC' }} />
          {vin && (
            <button style={{ height:31, padding:'0 11px', background:'#00C8A8', border:'none', color:'#04342C', fontWeight:500, fontSize:12 }}
              onClick={() => setInput(`Tell me everything about VIN ${vin}`)}>
              <i className="ti ti-search" style={{ fontSize:12 }} aria-hidden="true" /> Look up
            </button>
          )}
        </div>
        <form onSubmit={sendMessage} style={{ display:'flex', gap:7 }}>
          <input value={input} onChange={e => setInput(e.target.value)} placeholder="Ask LUMI AI about any vehicle…" style={{ flex:1, height:36, fontSize:13 }} disabled={loading} />
          <button type="submit" disabled={!input.trim() || loading}
            style={{ width:36, height:36, padding:0, background:'#0D2FA3', border:'none', color:'#fff', display:'flex', alignItems:'center', justifyContent:'center', opacity: !input.trim() ? .5 : 1 }}>
            <i className="ti ti-arrow-up" style={{ fontSize:15 }} aria-hidden="true" />
          </button>
        </form>
      </div>
    </div>
  );
}
